import { Component, OnInit } from '@angular/core';

import { ApiService } from '../../api.service';
import { Theme } from 'src/types/theme';
import { UserService } from 'src/app/user/user.service';

@Component({
    selector: 'app-theme-list',
    templateUrl: './theme-list.component.html',
    styleUrls: ['./theme-list.component.css']
})
export class ThemeListComponent implements OnInit {

    themes: Theme[] = [];
    isLoading: boolean = true;
    constructor(private apiService: ApiService, private userService: UserService) { }

    get isLoggedIn() {
        return this.userService.isLoggedIn;
    }

    ngOnInit() {
        this.apiService.getThemes().subscribe({
            next: (themes) => {
                this.themes = themes;
                this.isLoading = false;
            },
            error: (error) => {
                console.error(error);
                this.isLoading = false;
            }
        });
    }

    checkIsSubscribed(theme: Theme) {
        return theme.subscribers.includes(this.userService.user?._id || '');
    }
}
<div class="theme-title">
    <app-loader *ngIf="isLoading"></app-loader>
    <app-welcome-message *ngIf="!isLoading && !isLoggedIn"></app-welcome-message>
    <div
        class="theme-container"
        *ngFor="let theme of themes"
    >
        <div class="theme-name-wrapper">
            <div class="theme-name">
                <a
                    [routerLink]="[theme._id, 'details']"
                    class="normal"
                >
                    <h2>{{ theme.themeName | truncate: 25 }}</h2>
                </a>
                <div class="columns">
                    <div>
                        <p>Date: <time>{{ theme.created_at | elapsedTime }}</time></p>
                        <div class="nick-name">
                            <p>Username: <span>{{ theme.userId.username }}</span></p>
                        </div>
                    </div>
                    <div class="subscribers">
                        <button
                            *ngIf="!checkIsSubscribed(theme) && isLoggedIn"
                            class="subscribe"
                        >Subscribe</button>
                        <button
                            *ngIf="checkIsSubscribed(theme) && isLoggedIn"
                            class="unsubscribe"
                        >Unsubscribe</button>
                        <p>Subscribers: <span>{{ theme.subscribers.length }}</span></p>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>
